package edu.library.repository;

import edu.library.model.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository;
import java.math.BigDecimal; import java.sql.Date; import java.time.LocalDate; import java.util.*;
import edu.library.service.FineCalculator;

/** Spring JDBC repository for students, transactions, fines, dashboard and reports. */
@Repository
public class LibraryRepository {
    private final JdbcTemplate jdbc;
    public LibraryRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
    private static final org.springframework.jdbc.core.RowMapper<Student> STUDENT=(r,n)->new Student(r.getLong("id"),r.getString("full_name"),r.getString("email"),r.getString("department"));
    private static final org.springframework.jdbc.core.RowMapper<Issue> ISSUE=(r,n)->new Issue(r.getLong("id"),r.getString("title"),r.getString("full_name"),r.getString("email"),r.getDate("issue_date").toLocalDate(),r.getDate("due_date").toLocalDate(),r.getDate("return_date")==null?null:r.getDate("return_date").toLocalDate(),r.getString("status"));
    private static final String ISSUE_SELECT="SELECT i.id,b.title,s.full_name,s.email,i.issue_date,i.due_date,i.return_date,i.status FROM book_issues i JOIN books b ON b.id=i.book_id JOIN students s ON s.id=i.student_id";
    public List<Student> students(String q){String t="%"+(q==null?"":q.trim())+"%";return jdbc.query("SELECT * FROM students WHERE full_name LIKE ? OR email LIKE ? OR department LIKE ? ORDER BY full_name",STUDENT,t,t,t);}
    public Optional<Student> student(long id){return jdbc.query("SELECT * FROM students WHERE id=?",STUDENT,id).stream().findFirst();}
    public boolean lockStudent(long id){return !jdbc.query("SELECT id FROM students WHERE id=? FOR UPDATE",(r,n)->r.getLong(1),id).isEmpty();}
    public void saveStudent(Student s){if(s.getId()==null)jdbc.update("INSERT INTO students(full_name,email,department) VALUES(?,?,?)",s.getFullName().trim(),s.getEmail().trim().toLowerCase(),s.getDepartment().trim());else if(jdbc.update("UPDATE students SET full_name=?,email=?,department=? WHERE id=?",s.getFullName().trim(),s.getEmail().trim().toLowerCase(),s.getDepartment().trim(),s.getId())!=1)throw new IllegalArgumentException("Student not found");}
    public boolean deleteStudent(long id){return jdbc.update("DELETE FROM students WHERE id=? AND NOT EXISTS (SELECT 1 FROM book_issues WHERE student_id=?)",id,id)==1;}
    public List<Student> studentOptions(){return jdbc.query("SELECT * FROM students ORDER BY full_name",STUDENT);}
    public List<Issue> issues(String status){String where=status==null||status.isBlank()?"":status.equals("OVERDUE")?" WHERE i.status='ACTIVE' AND i.due_date<CURRENT_DATE":" WHERE i.status=?";return status==null||status.isBlank()||status.equals("OVERDUE")?jdbc.query(ISSUE_SELECT+where+" ORDER BY i.issue_date DESC,i.id DESC",ISSUE):jdbc.query(ISSUE_SELECT+where+" ORDER BY i.issue_date DESC,i.id DESC",ISSUE,status);}
    public List<Issue> history(long studentId){return jdbc.query(ISSUE_SELECT+" WHERE s.id=? ORDER BY i.issue_date DESC",ISSUE,studentId);}
    public int activeCount(long studentId){return jdbc.queryForObject("SELECT COUNT(*) FROM book_issues WHERE student_id=? AND status='ACTIVE'",Integer.class,studentId);}
    public boolean issueBook(long studentId,long bookId){int changed=jdbc.update("UPDATE books SET available_copies=available_copies-1 WHERE id=? AND archived=FALSE AND available_copies>0",bookId);if(changed!=1)return false;LocalDate today=LocalDate.now();jdbc.update("INSERT INTO book_issues(book_id,student_id,issue_date,due_date,status) VALUES(?,?,?,?, 'ACTIVE')",bookId,studentId,Date.valueOf(today),Date.valueOf(today.plusDays(14)));return true;}
    public boolean returnIssue(long issueId){List<java.util.Map<String,Object>> rows=jdbc.queryForList("SELECT book_id,due_date FROM book_issues WHERE id=? AND status='ACTIVE' FOR UPDATE",issueId);if(rows.isEmpty())return false;long bookId=((Number)rows.get(0).get("book_id")).longValue();LocalDate due=((Date)rows.get(0).get("due_date")).toLocalDate();LocalDate returned=LocalDate.now();int changed=jdbc.update("UPDATE book_issues SET status='RETURNED',return_date=? WHERE id=? AND status='ACTIVE'",Date.valueOf(returned),issueId);if(changed!=1)return false;jdbc.update("UPDATE books SET available_copies=LEAST(total_copies,available_copies+1) WHERE id=?",bookId);int days=FineCalculator.overdueDays(due,returned);BigDecimal amount=FineCalculator.amount(days);jdbc.update("INSERT INTO fines(issue_id,amount,overdue_days) VALUES(?,?,?) ON DUPLICATE KEY UPDATE amount=VALUES(amount),overdue_days=VALUES(overdue_days)",issueId,amount,days);return true;}
    public List<Fine> fines(){return jdbc.query("SELECT f.id,f.issue_id,s.full_name,b.title,f.amount,f.overdue_days,f.paid FROM fines f JOIN book_issues i ON i.id=f.issue_id JOIN students s ON s.id=i.student_id JOIN books b ON b.id=i.book_id ORDER BY f.paid,f.id DESC",(r,n)->new Fine(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getBigDecimal(5),r.getInt(6),r.getBoolean(7)));}
    public List<Fine> finesForStudent(long studentId){return jdbc.query("SELECT f.id,f.issue_id,s.full_name,b.title,f.amount,f.overdue_days,f.paid FROM fines f JOIN book_issues i ON i.id=f.issue_id JOIN students s ON s.id=i.student_id JOIN books b ON b.id=i.book_id WHERE s.id=? ORDER BY f.id DESC",(r,n)->new Fine(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getBigDecimal(5),r.getInt(6),r.getBoolean(7)),studentId);}
    public void payFine(long id){int changed=jdbc.update("UPDATE fines SET paid=TRUE,paid_at=CURRENT_TIMESTAMP WHERE id=? AND paid=FALSE",id);if(changed!=1)throw new IllegalArgumentException("Fine was not found or has already been paid");}
    public Map<String,Object> dashboard(){Map<String,Object> m=new LinkedHashMap<>();m.put("books",jdbc.queryForObject("SELECT COUNT(*) FROM books WHERE archived=FALSE",Integer.class));m.put("students",jdbc.queryForObject("SELECT COUNT(*) FROM students",Integer.class));m.put("issued",jdbc.queryForObject("SELECT COUNT(*) FROM book_issues WHERE status='ACTIVE'",Integer.class));m.put("available",jdbc.queryForObject("SELECT COALESCE(SUM(available_copies),0) FROM books WHERE archived=FALSE",Integer.class));m.put("overdue",jdbc.queryForObject("SELECT COUNT(*) FROM book_issues WHERE status='ACTIVE' AND due_date<CURRENT_DATE",Integer.class));m.put("collected",jdbc.queryForObject("SELECT COALESCE(SUM(amount),0) FROM fines WHERE paid=TRUE",BigDecimal.class));m.put("pending",jdbc.queryForObject("SELECT COALESCE(SUM(amount),0) FROM fines WHERE paid=FALSE",BigDecimal.class));return m;}
}
